// after the discount. The discount is the coupon's on the invoice when one applies (CouponPercentOff of the subtotal, or
// CouponAmountOff but never more than the subtotal), and DiscountPercent of the subtotal otherwise. The discount and the
// tax are each rounded half away from zero to a whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := money.Percent(subtotal, inv.DiscountPercent)
	switch {
	case inv.CouponAmountOff != 0:
		discount = min(inv.CouponAmountOff, subtotal)
	case inv.CouponPercentOff != 0:
