// couponFor returns the coupon that discounts the invoice made at now for the period of sub that starts at start, if one
// does. A coupon discounts the invoices made after it was applied: once, only the first of them; repeating, those whose
// period starts less than its months after the redemption; forever, all of them. An amount off applies only in the plan's
// currency.
func (s *Service) couponFor(sub store.Subscription, plan store.Plan, start, now time.Time) (store.Coupon, bool) {
	if sub.Coupon == "" || sub.CouponRedeemedAt == nil || !now.After(*sub.CouponRedeemedAt) {
		return store.Coupon{}, false
	}
	redeemed := *sub.CouponRedeemedAt
	c, ok := s.Store.Coupon(sub.OrgID, sub.Coupon)
	if !ok || (c.AmountOff != 0 && c.Currency != plan.Currency) {
		return store.Coupon{}, false
	}
	switch c.Duration {
	case store.Once:
		for _, inv := range s.Store.ListInvoices(sub.OrgID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
			if inv.Coupon == c.Code {
				return store.Coupon{}, false
			}
		}
	case store.Repeating:
		if !start.Before(redeemed.AddDate(0, c.DurationInMonths, 0)) {
			return store.Coupon{}, false
		}
	}
	return c, true
}

