package store

import (
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

func TestCouponValidation(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	ok := Coupon{OrgID: o.ID, Code: "SAVE10", PercentOff: 10, Duration: Forever}
	for name, c := range map[string]Coupon{
		"short code":          {OrgID: o.ID, Code: "AB", PercentOff: 10, Duration: Forever},
		"long code":           {OrgID: o.ID, Code: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456", PercentOff: 10, Duration: Forever},
		"space in code":       {OrgID: o.ID, Code: "SAVE 10", PercentOff: 10, Duration: Forever},
		"neither discount":    {OrgID: o.ID, Code: "NONE", Duration: Forever},
		"both discounts":      {OrgID: o.ID, Code: "BOTH", PercentOff: 10, AmountOff: 500, Currency: money.USD, Duration: Forever},
		"percent 101":         {OrgID: o.ID, Code: "TOOMUCH", PercentOff: 101, Duration: Forever},
		"currency on percent": {OrgID: o.ID, Code: "CURR", PercentOff: 10, Currency: money.USD, Duration: Forever},
		"amount without currency": {OrgID: o.ID, Code: "NOCUR", AmountOff: 500, Duration: Forever},
		"unknown duration":    {OrgID: o.ID, Code: "WHEN", PercentOff: 10, Duration: "monthly"},
		"repeating no months": {OrgID: o.ID, Code: "REP", PercentOff: 10, Duration: Repeating},
		"repeating 37 months": {OrgID: o.ID, Code: "REP37", PercentOff: 10, Duration: Repeating, DurationInMonths: 37},
		"once with months":    {OrgID: o.ID, Code: "ONCEM", PercentOff: 10, Duration: Once, DurationInMonths: 3},
		"negative redemptions": {OrgID: o.ID, Code: "NEG", PercentOff: 10, Duration: Forever, MaxRedemptions: -1},
	} {
		if _, err := s.CreateCoupon(c, t0); !errors.Is(err, ErrInvalid) {
			t.Errorf("%s: CreateCoupon = %v, want ErrInvalid", name, err)
		}
	}
	if _, err := s.CreateCoupon(ok, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: o.ID, Code: "WELCOME", AmountOff: 500, Currency: money.EUR, Duration: Once}, t0); err != nil {
		t.Fatalf("a valid amount coupon: %v", err)
	}
}

func TestCouponCodesAreUniqueIgnoringCase(t *testing.T) {
	s := New()
	acme, globex := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "Spring_24", PercentOff: 10, Duration: Forever}, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "SPRING_24", PercentOff: 5, Duration: Once}, t0); !errors.Is(err, ErrCodeTaken) {
		t.Fatalf("same code, other case: %v, want ErrCodeTaken", err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: globex.ID, Code: "spring_24", PercentOff: 5, Duration: Once}, t0); err != nil {
		t.Fatalf("another organization may use the code: %v", err)
	}
	if c, ok := s.Coupon(acme.ID, "spring_24"); !ok || c.Code != "Spring_24" {
		t.Fatalf("Coupon = %+v, %v", c, ok)
	}
	if _, ok := s.Coupon(globex.ID, "Spring_24"); !ok {
		t.Fatal("another organization's coupon was not found by its own code")
	}
	if n := len(s.Coupons(acme.ID)); n != 1 {
		t.Fatalf("Coupons = %d, want 1", n)
	}
}

// couponWorld is an organization with a customer and a monthly plan of 20.00 USD, and a subscription to it.
func couponWorld(t *testing.T) (*Store, Org, Subscription) {
	t.Helper()
	s := New()
	o := newOrg(t, s, "Acme")
	c, err := s.CreateCustomer(o.ID, "Jane", "jane@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	p, err := s.CreatePlan(Plan{OrgID: o.ID, Name: "Team", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	if err != nil {
		t.Fatal(err)
	}
	sub, err := s.CreateSubscription(Subscription{OrgID: o.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
	if err != nil {
		t.Fatal(err)
	}
	return s, o, sub
}

func TestApplyCouponRefusals(t *testing.T) {
	s, o, sub := couponWorld(t)
	mk := func(c Coupon) {
		t.Helper()
		c.OrgID = o.ID
		if _, err := s.CreateCoupon(c, t0); err != nil {
			t.Fatal(err)
		}
	}
	mk(Coupon{Code: "GONE", PercentOff: 10, Duration: Forever, RedeemBy: ptrTime(t0.Add(-time.Hour))})
	mk(Coupon{Code: "ONE", PercentOff: 10, Duration: Forever, MaxRedemptions: 1})
	mk(Coupon{Code: "EURO", AmountOff: 500, Currency: money.EUR, Duration: Forever})
	mk(Coupon{Code: "OK", PercentOff: 10, Duration: Forever})

	for code, want := range map[string]error{
		"NOPE":  ErrNotFound,
		"GONE":  ErrCouponExpired,
		"EURO":  ErrCurrencyMismatch,
	} {
		if _, err := s.ApplyCoupon(o.ID, sub.ID, code, t0); !errors.Is(err, want) {
			t.Errorf("%s: ApplyCoupon = %v, want %v", code, err, want)
		}
	}

	// A coupon with one redemption: the first subscription has it, a second cannot.
	if _, err := s.ApplyCoupon(o.ID, sub.ID, "ONE", t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(o.ID, sub.ID, "OK", t0); !errors.Is(err, ErrCouponAlreadyApplied) {
		t.Fatalf("a second coupon: %v, want ErrCouponAlreadyApplied", err)
	}
	second, err := s.CreateSubscription(Subscription{OrgID: o.ID, CustomerID: sub.CustomerID, PlanID: sub.PlanID, Quantity: 1, Status: Active}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(o.ID, second.ID, "one", t0); !errors.Is(err, ErrCouponExhausted) {
		t.Fatalf("exhausted: %v, want ErrCouponExhausted", err)
	}
	if n := s.TimesRedeemed(o.ID, "ONE"); n != 1 {
		t.Fatalf("TimesRedeemed = %d, want 1", n)
	}

	if _, err := s.UpdateSubscription(o.ID, second.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(o.ID, second.ID, "OK", t0); !errors.Is(err, ErrSubscriptionCanceled) {
		t.Fatalf("canceled: %v, want ErrSubscriptionCanceled", err)
	}
}

func TestApplyCouponRecordsTheRedemptionTime(t *testing.T) {
	s, o, sub := couponWorld(t)
	if _, err := s.CreateCoupon(Coupon{OrgID: o.ID, Code: "OK", PercentOff: 10, Duration: Forever}, t0); err != nil {
		t.Fatal(err)
	}
	at := t0.Add(72 * time.Hour)
	got, err := s.ApplyCoupon(o.ID, sub.ID, "OK", at)
	if err != nil {
		t.Fatal(err)
	}
	if got.Coupon != "OK" || got.CouponRedeemedAt == nil || !got.CouponRedeemedAt.Equal(at) {
		t.Fatalf("subscription = %+v", got)
	}
	if stored, _ := s.Subscription(o.ID, sub.ID); stored.CouponRedeemedAt == nil || !stored.CouponRedeemedAt.Equal(at) {
		t.Fatalf("stored subscription = %+v", stored)
	}
}

func ptrTime(t time.Time) *time.Time { return &t }

