func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}}
	// The coupon replaces the subscription's own discount: subtotal 5499, 25% of it is 1374.75 -> 1375; taxable 4124; tax 340.23 -> 340.
	got := Compute(store.Invoice{Lines: lines, DiscountPercent: 10, TaxRateBP: 825, Coupon: "QUARTER", CouponPercentOff: 25})
	if want := (Totals{Subtotal: 5499, Discount: 1375, Tax: 340, Total: 4464}); got != want {
		t.Fatalf("percent coupon: Compute = %+v, want %+v", got, want)
	}
	// An amount off takes that much off the subtotal, and never more than the subtotal.
	got = Compute(store.Invoice{Lines: lines, Coupon: "FIVE", CouponAmountOff: 500})
	if want := (Totals{Subtotal: 5499, Discount: 500, Total: 4999}); got != want {
		t.Fatalf("amount coupon: Compute = %+v, want %+v", got, want)
	}
	got = Compute(store.Invoice{Lines: lines, Coupon: "BIG", CouponAmountOff: 100000})
	if want := (Totals{Subtotal: 5499, Discount: 5499}); got != want {
		t.Fatalf("amount coupon above the subtotal: Compute = %+v, want %+v", got, want)
	}
}

