func TestRepeatingCouponDiscountsTheInvoicesItCovers(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1, DiscountPercent: 10})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Store.CreateCoupon(store.Coupon{OrgID: e.Acme.ID, Code: "SPRING", PercentOff: 25, Duration: store.Repeating, DurationInMonths: 2}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	applied, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "spring")
	if err != nil || applied.Coupon != "SPRING" || applied.CouponRedeemedAt == nil {
		t.Fatalf("apply = %+v, %v", applied, err)
	}
	for range 3 {
		cur, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		e.Clock.Set(cur.CurrentPeriodEnd)
		if _, err := e.Subs.RenewDue(ctx); err != nil {
			t.Fatal(err)
		}
	}
	// The first invoice was made before the coupon. The second is the only one whose period starts within two months of
	// the redemption: the third starts exactly two months after it.
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	want := []struct {
		coupon   string
		discount int64
	}{{"", 200}, {"SPRING", 500}, {"", 200}, {"", 200}}
	if len(invs) != len(want) {
		t.Fatalf("invoices = %d, want %d", len(invs), len(want))
	}
	for i, w := range want {
		if invs[i].Coupon != w.coupon || billing.Compute(invs[i]).Discount != w.discount {
			t.Errorf("invoice %d: coupon %q, discount %d; want %q, %d", i, invs[i].Coupon, billing.Compute(invs[i]).Discount, w.coupon, w.discount)
		}
	}
	if invs[1].DiscountPercent != 0 {
		t.Errorf("the coupon's invoice still carries the subscription's discount: %d", invs[1].DiscountPercent)
	}
}

func TestOnceCouponDiscountsOnlyTheFirstInvoiceAfterApplying(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Store.CreateCoupon(store.Coupon{OrgID: e.Acme.ID, Code: "FIVEOFF", AmountOff: 500, Currency: money.USD, Duration: store.Once}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.ApplyCoupon(ctx, e.Acme.ID, sub.ID, "FIVEOFF"); err != nil {
		t.Fatal(err)
	}
	for range 2 {
		cur, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		e.Clock.Set(cur.CurrentPeriodEnd)
		if _, err := e.Subs.RenewDue(ctx); err != nil {
			t.Fatal(err)
		}
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 || invs[0].Coupon != "" || invs[1].Coupon != "FIVEOFF" || invs[2].Coupon != "" {
		t.Fatalf("invoices = %+v, want the coupon on the first one made after applying only", invs)
	}
	if got := billing.Compute(invs[1]); got.Discount != 500 || got.Total != 1500 {
		t.Fatalf("the coupon's invoice = %+v", got)
	}
	if got := billing.Compute(invs[2]); got.Discount != 0 {
		t.Fatalf("the invoice after it = %+v", got)
	}
}
