func TestCoupons(t *testing.T) {
	e := apitest.New(t)
	type coupon struct {
		Code          string `json:"code"`
		PercentOff    int    `json:"percent_off"`
		AmountOff     int64  `json:"amount_off"`
		Currency      string `json:"currency"`
		Duration      string `json:"duration"`
		TimesRedeemed int    `json:"times_redeemed"`
	}
	var created coupon
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "Spring_24", "amount_off": "5.00", "currency": "USD", "duration": "once"}, &created)
	if created.Code != "Spring_24" || created.AmountOff != 500 || created.Currency != "USD" || created.PercentOff != 0 || created.Duration != "once" {
		t.Fatalf("created = %+v", created)
	}
	if r := e.Do("POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "spring_24", "percent_off": 10, "duration": "forever"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "code_taken" {
		t.Fatalf("same code, other case: %s", r)
	}
	// The same code is free in another organization.
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Globex.Key, map[string]any{"code": "spring_24", "percent_off": 10, "duration": "forever"}, nil)

	for _, body := range []map[string]any{
		{"code": "ab", "percent_off": 10, "duration": "forever"},
		{"code": "bad code", "percent_off": 10, "duration": "forever"},
		{"code": "NEITHER", "duration": "forever"},
		{"code": "BOTHXX", "percent_off": 10, "amount_off": "5.00", "currency": "USD", "duration": "forever"},
		{"code": "ZEROPCT", "percent_off": 0, "duration": "forever"},
		{"code": "TOOMUCH", "percent_off": 101, "duration": "forever"},
		{"code": "ZEROAMT", "amount_off": "0", "currency": "USD", "duration": "forever"},
		{"code": "NOCUR", "amount_off": "5.00", "duration": "forever"},
		{"code": "BADCUR", "amount_off": "5.00", "currency": "XXX", "duration": "forever"},
		{"code": "PCTCUR", "percent_off": 10, "currency": "USD", "duration": "forever"},
		{"code": "MONTHLY", "percent_off": 10, "duration": "monthly"},
		{"code": "REPNOM", "percent_off": 10, "duration": "repeating"},
		{"code": "REP37", "percent_off": 10, "duration": "repeating", "duration_in_months": 37},
		{"code": "ONCEM", "percent_off": 10, "duration": "once", "duration_in_months": 3},
		{"code": "FOREVM", "percent_off": 10, "duration": "forever", "duration_in_months": 0},
		{"code": "MAXZERO", "percent_off": 10, "duration": "forever", "max_redemptions": 0},
		{"code": "BADTIME", "percent_off": 10, "duration": "forever", "redeem_by": "tomorrow"},
	} {
		if r := e.Do("POST", "/v1/coupons", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid" {
			t.Errorf("%v: %s", body, r)
		}
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "SAVE10", "percent_off": 10, "duration": "repeating", "duration_in_months": 2, "max_redemptions": 5, "redeem_by": "2027-01-01T00:00:00Z"}, nil)

	var got coupon
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/spring_24", e.Acme.Key, nil, &got)
	if got.Code != "Spring_24" || got.TimesRedeemed != 0 {
		t.Fatalf("get = %+v", got)
	}
	if r := e.Do("GET", "/v1/coupons/NOPE", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("missing: %s", r)
	}
	var all struct{ Items []coupon }
	e.MustDo(http.StatusOK, "GET", "/v1/coupons", e.Acme.Key, nil, &all)
	if len(all.Items) != 2 || all.Items[0].Code != "Spring_24" || all.Items[1].Code != "SAVE10" {
		t.Fatalf("list = %+v, want the organization's coupons, oldest first", all.Items)
	}

	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	newSub := func() store.Subscription {
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "quantity": 1}, &sub)
		return sub
	}
	apply := func(sub store.Subscription, code string) *apitest.Response {
		return e.Do("POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]any{"code": code})
	}

	sub := newSub()
	if r := apply(sub, "NOPE"); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("unknown coupon: %s", r)
	}
	var applied store.Subscription
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]any{"code": "spring_24"}, &applied)
	if applied.Coupon != "Spring_24" || applied.CouponRedeemedAt == nil || !applied.CouponRedeemedAt.Equal(e.Clock.Now()) {
		t.Fatalf("applied = %+v", applied)
	}
	if r := apply(sub, "SAVE10"); r.Code != http.StatusConflict || r.Map(t)["error"] != "coupon_already_applied" {
		t.Fatalf("second coupon: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/Spring_24", e.Acme.Key, nil, &got)
	if got.TimesRedeemed != 1 {
		t.Fatalf("times_redeemed = %d, want 1", got.TimesRedeemed)
	}

	// A coupon redeemed after its redeem-by time is refused.
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "LATE", "percent_off": 10, "duration": "forever", "redeem_by": "2026-01-01T00:00:00Z"}, nil)
	if r := apply(newSub(), "LATE"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_expired" {
		t.Fatalf("expired: %s", r)
	}
	// An amount off in another currency than the plan's is refused.
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "EUROS", "amount_off": "5.00", "currency": "EUR", "duration": "forever"}, nil)
	if r := apply(newSub(), "EUROS"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "currency_mismatch" {
		t.Fatalf("currency: %s", r)
	}
	// A coupon with one redemption cannot be applied to a second subscription.
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "ONCE_ONLY", "percent_off": 10, "duration": "forever", "max_redemptions": 1}, nil)
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+newSub().ID+"/coupon", e.Acme.Key, map[string]any{"code": "ONCE_ONLY"}, nil)
	if r := apply(newSub(), "ONCE_ONLY"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_exhausted" {
		t.Fatalf("exhausted: %s", r)
	}
	// A canceled subscription cannot take a coupon.
	canceled := newSub()
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+canceled.ID+"/cancel", e.Acme.Key, nil, nil)
	if r := apply(canceled, "SAVE10"); r.Code != http.StatusConflict || r.Map(t)["error"] != "subscription_canceled" {
		t.Fatalf("canceled: %s", r)
	}

	// The coupon discounts the renewal that follows it, and the invoice says so.
	e.Clock.Set(sub.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(context.Background()); err != nil {
		t.Fatal(err)
	}
	type invoice struct {
		Coupon   string `json:"coupon"`
		Discount int64  `json:"discount"`
		Total    int64  `json:"total"`
	}
	var invs struct{ Items []invoice }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?subscription_id="+sub.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 2 || invs.Items[0].Coupon != "" || invs.Items[1].Coupon != "Spring_24" || invs.Items[1].Discount != 500 || invs.Items[1].Total != 1500 {
		t.Fatalf("invoices = %+v", invs.Items)
	}
}

