package store

import (
	"regexp"
	"sort"
	"strings"
	"time"
)

// ---- coupons

var couponCode = regexp.MustCompile(`^[A-Za-z0-9_-]{3,32}$`)

// CreateCoupon adds a coupon. Its code must be unique in the organization, ignoring case. A coupon is either percent off
// (PercentOff) or amount off (AmountOff in Currency), never both.
func (s *Store) CreateCoupon(c Coupon, now time.Time) (Coupon, error) {
	if err := checkCoupon(c); err != nil {
		return Coupon{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[c.OrgID]; !ok {
		return Coupon{}, ErrNotFound
	}
	if _, ok := s.findCoupon(c.OrgID, c.Code); ok {
		return Coupon{}, ErrCodeTaken
	}
	c.ID = s.newID("coup")
	c.CreatedAt = now.UTC()
	s.coupons[c.ID] = copyCoupon(c)
	return copyCoupon(c), nil
}

func checkCoupon(c Coupon) error {
	pct, amt := c.PercentOff != 0, c.AmountOff != 0
	switch {
	case !couponCode.MatchString(c.Code):
		return invalid("a coupon code is 3 to 32 letters, digits, dashes or underscores")
	case pct == amt:
		return invalid("a coupon takes exactly one of percent_off and amount_off")
	case pct && (c.PercentOff < 1 || c.PercentOff > 100):
		return invalid("percent_off is 1 to 100")
	case pct && c.Currency != "":
		return invalid("only amount_off takes a currency")
	case amt && (c.AmountOff < 0 || !c.Currency.Valid()):
		return invalid("amount_off needs a positive amount and a known currency")
	case c.Duration != Once && c.Duration != Repeating && c.Duration != Forever:
		return invalid("a coupon lasts once, repeating or forever")
	case c.Duration == Repeating && (c.DurationInMonths < 1 || c.DurationInMonths > 36):
		return invalid("a repeating coupon lasts 1 to 36 months")
	case c.Duration != Repeating && c.DurationInMonths != 0:
		return invalid("duration_in_months is for repeating coupons only")
	case c.MaxRedemptions < 0:
		return invalid("max_redemptions is at least 1")
	}
	return nil
}

// findCoupon finds one of an organization's coupons by its code, ignoring case. The caller holds the lock.
func (s *Store) findCoupon(orgID, code string) (Coupon, bool) {
	for _, c := range s.coupons {
		if c.OrgID == orgID && strings.EqualFold(c.Code, code) {
			return copyCoupon(c), true
		}
	}
	return Coupon{}, false
}

// Coupon returns one of an organization's coupons, found by its code ignoring case.
func (s *Store) Coupon(orgID, code string) (Coupon, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.findCoupon(orgID, code)
}

// Coupons returns an organization's coupons, oldest first.
func (s *Store) Coupons(orgID string) []Coupon {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, copyCoupon(c))
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// TimesRedeemed returns how many of an organization's subscriptions have the coupon with this code.
func (s *Store) TimesRedeemed(orgID, code string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.redeemedLocked(orgID, code)
}

// redeemedLocked counts the subscriptions that have the coupon with this code. The caller holds the lock.
func (s *Store) redeemedLocked(orgID, code string) int {
	n := 0
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.Coupon == code {
			n++
		}
	}
	return n
}

// ApplyCoupon applies one of the organization's coupons to a subscription. The time of applying, now, is the redemption
// time. It refuses a coupon that cannot be used then.
func (s *Store) ApplyCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	c, ok := s.findCoupon(orgID, code)
	if !ok {
		return Subscription{}, wrapNotFound("no such coupon")
	}
	switch {
	case sub.Status == Canceled:
		return Subscription{}, ErrSubscriptionCanceled
	case sub.Coupon != "":
		return Subscription{}, ErrCouponAlreadyApplied
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && s.redeemedLocked(orgID, c.Code) >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.AmountOff != 0 && c.Currency != s.plans[sub.PlanID].Currency:
		return Subscription{}, ErrCurrencyMismatch
	}
	at := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &at
	s.subs[subID] = copySub(sub)
	return copySub(sub), nil
}

func copyCoupon(c Coupon) Coupon {
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
	return c
}
EOF
