1	package api
2	
3	import (
4		"errors"
5		"net/http"
6		"time"
7	
8		"example.com/tally/internal/auth"
9		"example.com/tally/internal/money"
10		"example.com/tally/internal/store"
11	)
12	
13	// couponView is a coupon with how many subscriptions have it.
14	type couponView struct {
15		store.Coupon
16		TimesRedeemed int `json:"times_redeemed"`
17	}
18	
19	func (s *Server) viewCoupon(c store.Coupon) couponView {
20		return couponView{Coupon: c, TimesRedeemed: s.store.TimesRedeemed(c.OrgID, c.Code)}
21	}
22	
23	func invalidCoupon(w http.ResponseWriter, message string) {
24		writeError(w, http.StatusUnprocessableEntity, "invalid", message)
25	}
26	
27	// createCoupon takes either percent_off (1 to 100) or amount_off, a string in major units ("10.00") with its currency. The
28	// duration is once, forever, or repeating with duration_in_months (1 to 36). max_redemptions and redeem_by are optional.
29	func (s *Server) createCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
30		var in struct {
31			Code             string         `json:"code"`
32			PercentOff       *int           `json:"percent_off"`
33			AmountOff        *string        `json:"amount_off"`
34			Currency         money.Currency `json:"currency"`
35			Duration         store.Duration `json:"duration"`
36			DurationInMonths *int           `json:"duration_in_months"`
37			MaxRedemptions   *int           `json:"max_redemptions"`
38			RedeemBy         *string        `json:"redeem_by"`
39		}
40		if !decode(w, r, &in) {
41			return
42		}
43		c := store.Coupon{OrgID: p.OrgID, Code: in.Code, Currency: in.Currency, Duration: in.Duration}
44		if (in.PercentOff == nil) == (in.AmountOff == nil) {
45			invalidCoupon(w, "give percent_off or amount_off, not both")
46			return
47		}
48		if in.PercentOff != nil {
49			c.PercentOff = *in.PercentOff
50		} else {
51			amount, err := money.ParseMajor(*in.AmountOff, in.Currency)
52			if err != nil {
53				invalidCoupon(w, err.Error())
54				return
55			}
56			c.AmountOff = amount
57		}
58		if in.DurationInMonths != nil {
59			if c.Duration != store.Repeating {
60				invalidCoupon(w, "duration_in_months is for repeating coupons only")
61				return
62			}
63			c.DurationInMonths = *in.DurationInMonths
64		}
65		if in.MaxRedemptions != nil {
66			if *in.MaxRedemptions < 1 {
67				invalidCoupon(w, "max_redemptions is at least 1")
68				return
69			}
70			c.MaxRedemptions = *in.MaxRedemptions
71		}
72		if in.RedeemBy != nil {
73			t, err := time.Parse(time.RFC3339, *in.RedeemBy)
74			if err != nil {
75				invalidCoupon(w, "redeem_by is an RFC 3339 time")
76				return
77			}
78			c.RedeemBy = &t
79		}
80		coupon, err := s.store.CreateCoupon(c, s.clock.Now())
81		switch {
82		case errors.Is(err, store.ErrCodeTaken):
83			writeError(w, http.StatusConflict, "code_taken", err.Error())
84		case err != nil:
85			s.storeError(w, err)
86		default:
87			writeJSON(w, http.StatusCreated, s.viewCoupon(coupon))
88		}
89	}
90	
91	func (s *Server) listCoupons(w http.ResponseWriter, r *http.Request, p auth.Principal) {
92		items := []couponView{}
93		for _, c := range s.store.Coupons(p.OrgID) {
94			items = append(items, s.viewCoupon(c))
95		}
96		writeJSON(w, http.StatusOK, list{Items: items})
97	}
98	
99	func (s *Server) getCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
100		c, ok := s.store.Coupon(p.OrgID, r.PathValue("code"))
101		if !ok {
102			writeError(w, http.StatusNotFound, "not_found", "no such coupon")
103			return
104		}
105		writeJSON(w, http.StatusOK, s.viewCoupon(c))
106	}
107	
108	// applyCoupon applies a coupon to a subscription: {"code": "..."}.
109	func (s *Server) applyCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
110		var in struct {
111			Code string `json:"code"`
112		}
113		if !decode(w, r, &in) {
114			return
115		}
116		sub, err := s.subs.ApplyCoupon(r.Context(), p.OrgID, r.PathValue("id"), in.Code)
117		switch {
118		case errors.Is(err, store.ErrNotFound):
119			writeError(w, http.StatusNotFound, "not_found", err.Error())
120		case errors.Is(err, store.ErrSubscriptionCanceled):
121			writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
122		case errors.Is(err, store.ErrCouponAlreadyApplied):
123			writeError(w, http.StatusConflict, "coupon_already_applied", err.Error())
124		case errors.Is(err, store.ErrCouponExpired):
125			writeError(w, http.StatusUnprocessableEntity, "coupon_expired", err.Error())
126		case errors.Is(err, store.ErrCouponExhausted):
127			writeError(w, http.StatusUnprocessableEntity, "coupon_exhausted", err.Error())
128		case errors.Is(err, store.ErrCurrencyMismatch):
129			writeError(w, http.StatusUnprocessableEntity, "currency_mismatch", err.Error())
130		case err != nil:
131			s.storeError(w, err)
132		default:
133			writeJSON(w, http.StatusOK, sub)
134		}
135	}
