// Coupon is a discount an organization offers: PercentOff percent, or AmountOff off a subscription's invoices for Duration.
// AmountOff is in minor units of Currency, and is set only when PercentOff is not. DurationInMonths is set only for a
// repeating coupon, and MaxRedemptions is 0 for no limit.
type Coupon struct {
	ID               string         `json:"id"`
	OrgID            string         `json:"org_id"`
	Code             string         `json:"code"`
	PercentOff       int            `json:"percent_off,omitempty"`
	AmountOff        int64          `json:"amount_off,omitempty"`
	Currency         money.Currency `json:"currency,omitempty"`
	Duration         Duration       `json:"duration"`
	DurationInMonths int            `json:"duration_in_months,omitempty"`
	MaxRedemptions   int            `json:"max_redemptions,omitempty"`
	RedeemBy         *time.Time     `json:"redeem_by,omitempty"`
	CreatedAt        time.Time      `json:"created_at"`
}

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// Coupon is the code of the coupon applied to the subscription, or "".
	Coupon string `json:"coupon"`
	// CouponRedeemedAt is when Coupon was applied. It discounts the invoices created after it.
	CouponRedeemedAt *time.Time `json:"coupon_redeemed_at,omitempty"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
	// Coupon is the code of the coupon that discounted the invoice, or "". Its terms are copied here when the invoice is
	// made, and the discount is then taken from them instead of DiscountPercent.
	Coupon           string `json:"coupon"`
	CouponPercentOff int    `json:"coupon_percent_off,omitempty"`
	CouponAmountOff  int64  `json:"coupon_amount_off,omitempty"`
}

